<script setup lang="ts">const shop=useShop();const route=useRoute();const form=reactive({name:shop.user?.name||'',email:shop.user?.email||'',phone:'',address:'',city:'Phnom Penh',delivery:'standard'});const errors=ref<string[]>([]);const coupon=ref(typeof route.query.coupon==='string'?route.query.coupon:'');const discount=computed(()=>coupon.value.toUpperCase()==='VY10'?shop.cartSubtotal*.1:0);const shipping=computed(()=>shop.cartSubtotal-discount.value>=75||shop.cartSubtotal===0?0:form.delivery==='express'?8:4.5);const total=computed(()=>shop.cartSubtotal-discount.value+shipping.value);function submit(){errors.value=[];if(!form.name.trim())errors.value.push('Name is required.');if(!/^\S+@\S+\.\S+$/.test(form.email))errors.value.push('Enter a valid email.');if(!form.phone.trim())errors.value.push('Phone number is required.');if(!form.address.trim())errors.value.push('Shipping address is required.');if(!form.city.trim())errors.value.push('City is required.');if(!shop.cart.length)errors.value.push('Your bag is empty.');if(errors.value.length){shop.notify('Please check the checkout form.','error');return}const order=shop.placeOrder({name:form.name,email:form.email,phone:form.phone,address:form.address,city:form.city},coupon.value);if(order)navigateTo({path:'/order-success',query:{order:order.id}})}</script>
<template><div class="mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8 py-10 sm:py-14"><p class="text-xs font-bold uppercase tracking-[.2em] text-brand">Almost yours</p><h1 class="mt-2 text-4xl font-semibold tracking-tight">Checkout<span class="text-brand">.</span></h1><div v-if="shop.cart.length" class="mt-8 grid gap-10 lg:grid-cols-[1fr_360px]"><form class="space-y-7" @submit.prevent="submit"><div v-if="errors.length" class="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700"><p v-for="error in errors" :key="error">• {{ error }}</p></div><section><h2 class="text-lg font-semibold">Contact details</h2><div class="mt-4 grid gap-4 sm:grid-cols-2"><label class="text-xs font-semibold">Full name<input v-model="form.name" required class="mt-2 w-full rounded-xl border border-gray-200 px-4 py-3 text-sm outline-none focus:border-brand"></label><label class="text-xs font-semibold">Email address<input v-model="form.email" type="email" required class="mt-2 w-full rounded-xl border border-gray-200 px-4 py-3 text-sm outline-none focus:border-brand"></label><label class="text-xs font-semibold sm:col-span-2">Phone number<input v-model="form.phone" required class="mt-2 w-full rounded-xl border border-gray-200 px-4 py-3 text-sm outline-none focus:border-brand" placeholder="+855 ..."></label></div></section><section><h2 class="text-lg font-semibold">Shipping address</h2><div class="mt-4 grid gap-4 sm:grid-cols-2"><label class="text-xs font-semibold sm:col-span-2">Street address<input v-model="form.address" required class="mt-2 w-full rounded-xl border border-gray-200 px-4 py-3 text-sm outline-none focus:border-brand"></label><label class="text-xs font-semibold sm:col-span-2">City / Province<input v-model="form.city" required class="mt-2 w-full rounded-xl border border-gray-200 px-4 py-3 text-sm outline-none focus:border-brand"></label></div></section><section><h2 class="text-lg font-semibold">Delivery method</h2><div class="mt-4 space-y-3"><label class="flex cursor-pointer items-center justify-between rounded-xl border p-4" :class="form.delivery==='standard'?'border-brand bg-blue-50/50':'border-gray-200'"><span class="flex items-center gap-3"><input v-model="form.delivery" type="radio" value="standard" class="accent-brand"><span><span class="block text-sm font-semibold">Standard delivery</span><span class="mt-1 block text-xs text-gray-500">3–5 business days · Free over $75</span></span></span><span class="text-sm font-semibold">{{ shop.cartSubtotal-discount>=75?'Free':'$4.50' }}</span></label><label class="flex cursor-pointer items-center justify-between rounded-xl border p-4" :class="form.delivery==='express'?'border-brand bg-blue-50/50':'border-gray-200'"><span class="flex items-center gap-3"><input v-model="form.delivery" type="radio" value="express" class="accent-brand"><span><span class="block text-sm font-semibold">Express delivery</span><span class="mt-1 block text-xs text-gray-500">1–2 business days · Demo option</span></span></span><span class="text-sm font-semibold">$8.00</span></label></div></section><div class="rounded-xl bg-amber-50 p-4 text-xs leading-5 text-amber-800">Demo checkout: this will create a local sample order only. No payment, email, or delivery booking will occur.</div><button type="submit" class="w-full rounded-full bg-brand px-6 py-4 text-xs font-bold uppercase tracking-wider text-white transition hover:bg-ink">Place demo order · ${{ total.toFixed(2) }}</button><NuxtLink to="/cart" class="block text-center text-xs text-gray-500 underline underline-offset-4">← Return to bag</NuxtLink></form><aside class="h-fit rounded-2xl bg-mist p-6"><h2 class="text-lg font-semibold">Your order</h2><div class="mt-5 space-y-4"><div v-for="line in shop.cart" :key="line.key" class="flex gap-3"><img :src="shop.productById(line.productId)?.images[0]" class="h-16 w-12 rounded-lg object-cover"><div class="min-w-0 flex-1"><p class="text-xs font-semibold">{{ shop.productById(line.productId)?.name }}</p><p class="mt-1 text-[10px] text-gray-500">{{ line.color }} / {{ line.size }} × {{ line.quantity }}</p></div><span class="text-xs font-semibold">${((shop.productById(line.productId)?shop.price(shop.productById(line.productId)!):0)*line.quantity).toFixed(2)}</span></div></div><div class="mt-6 space-y-3 border-t border-gray-200 pt-5 text-sm"><div class="flex justify-between"><span class="text-gray-500">Subtotal</span><span>${{ shop.cartSubtotal.toFixed(2) }}</span></div><div v-if="discount" class="flex justify-between text-green-700"><span>VY10 discount</span><span>−${{ discount.toFixed(2) }}</span></div><div class="flex justify-between"><span class="text-gray-500">Shipping</span><span>${{ shipping.toFixed(2) }}</span></div><div class="flex justify-between border-t border-gray-200 pt-4 font-bold"><span>Total</span><span>${{ total.toFixed(2) }}</span></div></div></aside></div><EmptyState v-else title="Your bag is empty" description="Add a few favorites before checking out." to="/shop" action-label="Browse the collection"/></div></template>
